<?php
require_once __DIR__ . '/../../../app/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST') api_response(['success'=>false,'mensaje'=>'Método no permitido.'],405);
$data=json_input();$usuario=trim((string)($data['usuario']??''));$password=(string)($data['password']??'');$s=db()->prepare('SELECT * FROM usuarios WHERE usuario=:u LIMIT 1');$s->execute(['u'=>$usuario]);$u=$s->fetch();if(!$u||!(bool)$u['activo']||!password_verify($password,$u['password_hash']))api_response(['success'=>false,'mensaje'=>'Credenciales inválidas.'],401);
$raw=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$hash=hash('sha256',$raw);$ttl=max(1,(int)(getenv('TOKEN_TTL_HOURS')?:168));db()->prepare("DELETE FROM api_tokens WHERE expira_en <= NOW()")->execute();db()->prepare("INSERT INTO api_tokens(usuario_id,token_hash,expira_en) VALUES(:uid,:h,NOW() + (CAST(:ttl AS INTEGER) * INTERVAL '1 hour'))")->execute(['uid'=>$u['id'],'h'=>$hash,'ttl'=>$ttl]);db()->prepare('UPDATE usuarios SET ultimo_acceso=NOW() WHERE id=:id')->execute(['id'=>$u['id']]);api_response(['success'=>true,'token'=>$raw,'usuario'=>['id'=>(int)$u['id'],'nombre'=>$u['nombre'],'usuario'=>$u['usuario'],'rol'=>$u['rol']]]);
